  D1220JSON

  def self.run
    model = Sketchup.active_model
    data = JSON.parse(DATA)
    model.start_operation('Build D1220', true)
    mats = {}
    data['mats'].each do |idx, name, r, g, b, a|
      m = model.materials[name] || model.materials.add(name)
      m.color = Sketchup::Color.new(r, g, b)
      m.alpha = a / 255.0 if a < 255
      mats[idx] = m
    end
    ceiling = model.layers['Ceiling'] || model.layers.add('Ceiling')
    build(model.active_entities, data['tree'], mats, ceiling)
    ceiling.visible = false
    view = model.active_view
    eye = Geom::Point3d.new(170, -260, 560)
    target = Geom::Point3d.new(170, 300, 0)
    view.camera = Sketchup::Camera.new(eye, target, Z_AXIS, true, 40)
    model.commit_operation
    view.zoom_extents
    UI.messagebox("D1220 built. Use File > Save As to save it in your SketchUp version.\nThe ceiling is on the 'Ceiling' tag (hidden).")
  rescue => e
    model.abort_operation
    UI.messagebox("D1220 build failed: #{e.message}")
    raise
  end

  def self.build(ents, node, mats, ceiling)
    grp = ents.add_group
    grp.name = node['n'].to_s
    grp.layer = ceiling if node['l'] == 'Ceiling'
    ge = grp.entities
    pts = node['v'].map { |x, y, z| Geom::Point3d.new(x, y, z) }
    node['f'].each do |mi, outer, holes|
      begin
        face = ge.add_face(outer.map { |i| pts[i] })
        next unless face
        holes.each do |h|
          hf = ge.add_face(h.map { |i| pts[i] })
          hf.erase! if hf && hf.valid?
        end
        if mi >= 0 && face.valid?
          face.material = mats[mi]
          face.back_material = mats[mi]
        end
      rescue ArgumentError
        # skip degenerate face
      end
    end
    ge.grep(Sketchup::Edge).each do |e|
      fs = e.faces
      next unless fs.length == 2
      if fs[0].normal.dot(fs[1].normal).abs > 0.45
        e.soft = true
        e.smooth = true
      end
    end
    node['c'].each { |c| build(ge, c, mats, ceiling) }
    grp.transformation = Geom::Transformation.new(node['t'])
    grp
  end
end

